const {app,BrowserWindow}=require('electron');const assert=require('node:assert/strict');const fs=require('node:fs/promises');const path=require('node:path');app.setPath('userData',process.argv[2]);
app.whenReady().then(async()=>{const win=new BrowserWindow({show:false,width:1280,height:850,webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false}});win.webContents.on('console-message',(_e,_l,message)=>console.log(message));await win.loadFile(process.argv[3]);const run=s=>win.webContents.executeJavaScript(s),until=async s=>{for(let i=0;i<250;i++){if(await run(s))return;await new Promise(r=>setTimeout(r,20));}throw Error('UI timeout '+s+' '+await run('document.body.innerText'));},click=label=>run(`[...document.querySelectorAll('button')].find(b=>b.textContent===${JSON.stringify(label)}).click()`),choose=(label,value)=>run(`{const e=document.querySelector('[aria-label="${label}"]');Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set.call(e,${JSON.stringify(value)});e.dispatchEvent(new Event('change',{bubbles:true}));}`),shot=async name=>{await run('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))');await new Promise(r=>setTimeout(r,100));await fs.mkdir(process.argv[4],{recursive:true});await fs.writeFile(path.join(process.argv[4],name+'.png'),(await win.webContents.capturePage()).toPNG());};
await until("document.body.textContent.includes('Synthetic contract review')");await run("[...document.querySelectorAll('button')].find(b=>b.textContent.includes('Synthetic contract review')).click()");await until("document.body.textContent.includes('contract.txt')");await click('Open');await until("!!document.querySelector('[aria-label=\"Internal attachment viewer\"]')");assert.equal(await run("document.body.textContent.includes('Synthetic contract appendix')"),true);await shot('01-mail-internal-preview');
await run("document.querySelector('[aria-label=\"Add contract.txt to chat\"]').click()");await until("document.body.textContent.includes('Add attachment to chat')");assert.equal(await run("window.copies.length"),0);await choose('Attachment workspace','remote');await until("document.body.textContent.includes('This uploads a copy')");await choose('Attachment chat','existing');await run('window.rerenderParent()');await new Promise(r=>setTimeout(r,30));assert.equal(await run("document.querySelector('[aria-label=\"Attachment chat\"]').value"),'existing');await shot('02-explicit-workspace-chat');await click('Cancel');assert.equal(await run("window.copies.length"),0);
await run("document.querySelector('[aria-label=\"Add contract.txt to chat\"]').click()");await choose('Attachment workspace','local');await until("document.querySelector('[aria-label=\"Attachment chat\"]').disabled===false");await choose('Attachment chat','existing');await click('Copy and add to draft');await until("!!document.querySelector('[aria-label=\"Chosen workspace chat\"]')");assert.equal(await run("window.copies.length"),2);assert.equal(await run("window.copies.every(v=>v.id==='server-local')"),true);assert.equal(await run("document.querySelector('textarea').value.startsWith('Existing instructions stay here.')"),true);assert.equal(await run("window.calls.some(v=>v.path?.includes('prompt')||v.path?.includes('outbox'))"),false);await shot('03-chat-draft-provenance');await run("localStorage.setItem('legalwork.server.urlOverride','http://127.0.0.1:9876');[...document.querySelectorAll('a')].find(a=>a.textContent==='Source email').click()");await until("!!document.querySelector('[aria-label=\"Add contract.txt to chat\"]')");await shot('04-return-to-mail');assert.equal(await run("window.calls.some(v=>v.path?.endsWith('/read')&&v.origin==='http://127.0.0.1:9876')"),true);
await run("document.querySelector('[aria-label=\"Add contract.txt to chat\"]').click()");await choose('Attachment workspace','local');await until("document.querySelector('[aria-label=\"Attachment chat\"]').disabled===false");await run('window.cancelCopy=true');await click('Copy and add to draft');await until("typeof window.releaseCopy==='function'");assert.equal(await run("window.calls.filter(v=>v.prepare).at(-1).sessionId"),null);await click('Cancel');await run('window.cancelCopy=false;window.releaseCopy()');await new Promise(r=>setTimeout(r,80));assert.equal(await run("window.copies.length"),3);assert.equal(await run("!!document.querySelector('[aria-label=\"Chosen workspace chat\"]')"),false);
await run("document.querySelector('[aria-label=\"Add contract.txt to chat\"]').click()");await click('Copy and add to draft');await until("!!document.querySelector('[aria-label=\"Chosen workspace chat\"]')");assert.equal(await run("window.copies.length"),5);assert.equal(await run("document.querySelector('textarea').value.startsWith('Existing instructions')"),false);await run('window.removed=true');await click('Return to source email');await until("document.body.textContent.includes('The source email is unavailable')");assert.equal(await run("window.copies.length"),5);console.log('MAIL_JOURNEY_PASS');win.destroy();app.quit();}).catch(error=>{console.error(error);app.exit(1);});
